import{_ as o,a0 as p,w as r,s as d,ao as n,I as a,x as e,a1 as t,A as l}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"如何编译 Linux 内核 | LCTT x X-CMD","titleTemplate":false,"description":"如何编译 Linux 内核 | LCTT (201805) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何编译 Linux 内核 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何编译 Linux 内核 | LCTT (201805) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201805/20180427 How to Compile a Linux Kernel","title":"如何编译 Linux 内核","tag":"201805","desc":""},"relativePath":"201805/20180427 How to Compile a Linux Kernel.md","filePath":"[post].md"}'),u={name:"201805/20180427 How to Compile a Linux Kernel.md"};function h(g,i,k,b,c,m){const s=p("Link");return r(),d("div",null,[i[23]||(i[23]=n('<h1 id="如何编译-linux-内核" tabindex="-1">如何编译 Linux 内核 <a class="header-anchor" href="#如何编译-linux-内核" aria-label="Permalink to “如何编译 Linux 内核”">​</a></h1><blockquote><p>Jack 将带你在 Ubuntu 16.04 服务器上走过内核编译之旅。</p></blockquote><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/chester-alvarez-644-unsplash.jpg?itok=aFxG9kUZ" alt=""></p><p>曾经有一段时间，升级 Linux 内核让很多用户打心里有所畏惧。在那个时候，升级内核包含了很多步骤，也需要很多时间。现在，内核的安装可以轻易地通过像 <code>apt</code> 这样的包管理器来处理。通过添加特定的仓库，你能很轻易地安装实验版本的或者指定版本的内核（比如针对音频产品的实时内核）。</p><p>考虑一下，既然升级内核如此容易，为什么你不愿意自行编译一个呢？这里列举一些可能的原因：</p><ul><li>你想要简单了解编译内核的过程</li><li>你需要启用或者禁用内核中特定的选项，因为它们没有出现在标准选项里</li><li>你想要启用标准内核中可能没有添加的硬件支持</li><li>你使用的发行版需要你编译内核</li><li>你是一个学生，而编译内核是你的任务</li></ul><p>不管出于什么原因，懂得如何编译内核是非常有用的，而且可以被视作一个通行权。当我第一次编译一个新的 Linux 内核（那是很久以前了），然后尝试从它启动，我从中（系统马上就崩溃了，然后不断地尝试和失败）感受到一种特定的兴奋。</p><p>既然这样，让我们来实验一下编译内核的过程。我将使用 Ubuntu 16.04 Server 来进行演示。在运行了一次常规的 <code>sudo apt upgrade</code> 之后，当前安装的内核版本是 <code>4.4.0-121</code>。我想要升级内核版本到 <code>4.17</code>， 让我们小心地开始吧。</p><p>有一个警告：强烈建议你在虚拟机里实验这个过程。基于虚拟机，你总能创建一个快照，然后轻松地从任何问题中回退出来。不要在产品机器上使用这种方式升级内核，除非你知道你在做什么。</p><h3 id="下载内核" tabindex="-1">下载内核 <a class="header-anchor" href="#下载内核" aria-label="Permalink to “下载内核”">​</a></h3>',10)),a("p",null,[i[1]||(i[1]=e("我们要做的第一件事是下载内核源码。在 ",-1)),t(s,{href:"https://www.kernel.org/"},{default:l(()=>[...i[0]||(i[0]=[e("Kernel.org",-1)])]),_:1}),i[2]||(i[2]=e(" 找到你要下载的所需内核的 URL。找到 URL 之后，使用如下命令（我以 ",-1)),i[3]||(i[3]=a("code",null,"4.17 RC2",-1)),i[4]||(i[4]=e(" 内核为例） 来下载源码文件:",-1))]),i[24]||(i[24]=n('<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>wget https://git.kernel.org/torvalds/t/linux-4.17-rc2.tar.gz</span></span></code></pre></div><p>在下载期间，有一些事需要去考虑。</p><h3 id="安装需要的环境" tabindex="-1">安装需要的环境 <a class="header-anchor" href="#安装需要的环境" aria-label="Permalink to “安装需要的环境”">​</a></h3><p>为了编译内核，我们首先得安装一些需要的环境。这可以通过一个命令来完成：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-get install git fakeroot build-essential ncurses-dev xz-utils libssl-dev bc flex libelf-dev bison</span></span></code></pre></div><p>务必注意：你将需要至少 128GB 的本地可用磁盘空间来完成内核的编译过程。因此你必须确保有足够的空间。</p><h3 id="解压源码" tabindex="-1">解压源码 <a class="header-anchor" href="#解压源码" aria-label="Permalink to “解压源码”">​</a></h3><p>在新下载的内核所在的文件夹下，使用该命令来解压内核：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>tar xvzf linux-4.17-rc2.tar.gz</span></span></code></pre></div><p>使用命令 <code>cd linux-4.17-rc2</code> 进入新生成的文件夹。</p><h3 id="配置内核" tabindex="-1">配置内核 <a class="header-anchor" href="#配置内核" aria-label="Permalink to “配置内核”">​</a></h3><p>在正式编译内核之前，我们首先必须配置需要包含哪些模块。实际上，有一些非常简单的方式来配置。使用一个命令，你能拷贝当前内核的配置文件，然后使用可靠的 <code>menuconfig</code> 命令来做任何必要的更改。使用如下命令来完成：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cp /boot/config-$(uname -r) .config</span></span></code></pre></div><p>现在你有一个配置文件了，输入命令 <code>make menuconfig</code>。该命令将打开一个配置工具（图 1），它可以让你遍历每个可用模块，然后启用或者禁用你需要或者不需要的模块。</p><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/kernel_compile_1.jpg?itok=ZNybYgEt" alt="menuconfig" title="menuconfig"></p><p><em>图 1: 运行中的 <code>make menuconfig</code></em></p><p>很有可能你会禁用掉内核中的一个重要部分，所以在 <code>menuconfig</code> 期间小心地一步步进行。如果你对某个选项不确定，不要去管它。或者更好的方法是使用我们拷贝的当前运行的内核的配置文件（因为我们知道它可以工作）。一旦你已经遍历了整个配置列表（它非常长），你就准备好开始编译了。</p><h3 id="编译和安装" tabindex="-1">编译和安装 <a class="header-anchor" href="#编译和安装" aria-label="Permalink to “编译和安装”">​</a></h3><p>现在是时候去实际地编译内核了。第一步是使用 <code>make</code> 命令去编译。调用 <code>make</code> 命令然后回答必要的问题（图 2）。这些问题取决于你将升级的现有内核以及升级后的内核。相信我，将会有非常多的问题要回答，因此你得预留大量的时间。</p><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/kernel_compile_2.jpg?itok=TYfV02wC" alt="make" title="make"></p><p><em>图 2: 回答 <code>make</code> 命令的问题</em></p><p>回答了长篇累牍的问题之后，你就可以用如下的命令安装那些之前启用的模块：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>make modules_install</span></span></code></pre></div><p>又来了，这个命令将耗费一些时间，所以要么坐下来看着编译输出，或者去做些其他事（因为编译期间不需要你的输入）。可能的情况是，你想要去进行别的任务（除非你真的喜欢看着终端界面上飞舞而过的输出）。</p><p>现在我们使用这个命令来安装内核：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo make install</span></span></code></pre></div><p>又一次，另一个将要耗费大量可观时间的命令。事实上，<code>make install</code> 命令将比 <code>make modules_install</code> 命令花费更多的时间。去享用午餐，配置一个路由器，将 Linux 安装在一些服务器上，或者小睡一会吧。</p><h3 id="启用内核作为引导" tabindex="-1">启用内核作为引导 <a class="header-anchor" href="#启用内核作为引导" aria-label="Permalink to “启用内核作为引导”">​</a></h3><p>一旦 <code>make install</code> 命令完成了，就是时候将内核启用来作为引导。使用这个命令来实现：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo update-initramfs -c -k 4.17-rc2</span></span></code></pre></div><p>当然，你需要将上述内核版本号替换成你编译完的。当命令执行完毕后，使用如下命令来更新 grub：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo update-grub</span></span></code></pre></div><p>现在你可以重启系统并且选择新安装的内核了。</p><h3 id="恭喜" tabindex="-1">恭喜! <a class="header-anchor" href="#恭喜" aria-label="Permalink to “恭喜!”">​</a></h3><p>你已经编译了一个 Linux 内核！它是一项耗费时间的活动；但是，最终你的 Linux 发行版将拥有一个定制的内核，同时你也将拥有一项被许多 Linux 管理员所倾向忽视的重要技能。</p>',35)),a("p",null,[i[6]||(i[6]=e("从 Linux 基金会和 edX 提供的免费 ",-1)),t(s,{href:"https://training.linuxfoundation.org/linux-courses/system-administration-training/introduction-to-linux"},{default:l(()=>[...i[5]||(i[5]=[e("“Introduction to Linux”",-1)])]),_:1}),i[7]||(i[7]=e(" 课程来学习更多的 Linux 知识。",-1))]),i[25]||(i[25]=a("hr",null,null,-1)),a("p",null,[i[9]||(i[9]=e("via: ",-1)),t(s,{href:"https://www.linux.com/learn/intro-to-linux/2018/4/how-compile-linux-kernel-0"},{default:l(()=>[...i[8]||(i[8]=[e("https://www.linux.com/learn/intro-to-linux/2018/4/how-compile-linux-kernel-0",-1)])]),_:1})]),a("p",null,[i[14]||(i[14]=e("作者：",-1)),t(s,{href:"https://www.linux.com/users/jlwallen"},{default:l(()=>[...i[10]||(i[10]=[e("Jack Wallen",-1)])]),_:1}),i[15]||(i[15]=e(" 选题：",-1)),t(s,{href:"https://github.com/lujun9972"},{default:l(()=>[...i[11]||(i[11]=[e("lujun9972",-1)])]),_:1}),i[16]||(i[16]=e(" 译者：",-1)),t(s,{href:"https://github.com/icecoobe"},{default:l(()=>[...i[12]||(i[12]=[e("icecoobe",-1)])]),_:1}),i[17]||(i[17]=e(" 校对：",-1)),t(s,{href:"https://github.com/wxy"},{default:l(()=>[...i[13]||(i[13]=[e("wxy",-1)])]),_:1})]),a("p",null,[i[20]||(i[20]=e("本文由 ",-1)),t(s,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...i[18]||(i[18]=[e("LCTT",-1)])]),_:1}),i[21]||(i[21]=e(" 原创编译，",-1)),t(s,{href:"https://linux.cn/"},{default:l(()=>[...i[19]||(i[19]=[e("Linux中国",-1)])]),_:1}),i[22]||(i[22]=e(" 荣誉推出",-1))])])}const w=o(u,[["render",h]]);export{C as __pageData,w as default};
